5	import {
6	  aws_certificatemanager as acm,
7	  aws_cloudfront as cloudfront,
8	  Duration,
9	  aws_cloudfront_origins as origins,
10	  aws_route53 as route53,
11	  aws_s3 as s3,
12	  aws_route53_targets as targets,
13	} from 'aws-cdk-lib';
14	import { ServerlessClamscan } from 'cdk-serverless-clamscan';
15	import { Construct } from 'constructs';
16	import { grantBucketAccessToOriginAccessIdentity } from './oai';
17	import { buildWaf } from './waf';
18	
19	/**
20	 * Binary storage bucket and CloudFront distribution.
21	 */
22	export class Storage extends Construct {
23	  storageBucket: s3.IBucket;
24	  keyGroup?: cloudfront.IKeyGroup;
25	  responseHeadersPolicy?: cloudfront.IResponseHeadersPolicy;
26	  waf?: wafv2.CfnWebACL;
27	  originAccessIdentity?: cloudfront.OriginAccessIdentity;
28	  originAccessPolicyStatement?: iam.PolicyStatement;
29	  distribution?: cloudfront.IDistribution;
30	  dnsRecord?: route53.IRecordSet;
31	
32	  constructor(parent: Construct, config: MedplumInfraConfig, region: string) {
33	    super(parent, 'Storage');
34	
35	    if (region === config.region) {
36	      // S3 bucket
37	      this.storageBucket = new s3.Bucket(this, 'StorageBucket', {
38	        bucketName: config.storageBucketName,
39	        publicReadAccess: false,
40	        blockPublicAccess: s3.BlockPublicAccess.BLOCK_ALL,
41	        encryption: s3.BucketEncryption.S3_MANAGED,
42	        enforceSSL: true,
43	        versioned: true,
44	      });
45	
46	      if (config.clamscanEnabled) {
47	        // ClamAV serverless scan
48	        const sc = new ServerlessClamscan(this, 'ServerlessClamscan', {
49	          defsBucketAccessLogsConfig: {
50	            logsBucket: s3.Bucket.fromBucketName(this, 'LoggingBucket', config.clamscanLoggingBucket),
51	            logsPrefix: config.clamscanLoggingPrefix,
52	          },
53	        });
54	        sc.addSourceBucket(this.storageBucket);
55	      }
56	    } else {
57	      // Otherwise, reference the bucket by name and region
58	      this.storageBucket = s3.Bucket.fromBucketAttributes(this, 'StorageBucket', {
59	        bucketName: config.storageBucketName,
60	        region: config.region,
61	      });
62	    }
63	
64	    if (region === 'us-east-1') {
65	      // Public key in PEM format
66	      let publicKey: cloudfront.IPublicKey;
67	      if (config.signingKeyId) {
68	        publicKey = cloudfront.PublicKey.fromPublicKeyId(this, 'StoragePublicKey', config.signingKeyId);
69	      } else {
70	        publicKey = new cloudfront.PublicKey(this, 'StoragePublicKey', {
71	          encodedKey: config.storagePublicKey,
72	        });
73	      }
74	
75	      // Authorized key group for presigned URLs
76	      this.keyGroup = new cloudfront.KeyGroup(this, 'StorageKeyGroup', {
77	        items: [publicKey],
78	      });
79	
80	      // HTTP response headers policy
81	      this.responseHeadersPolicy = new cloudfront.ResponseHeadersPolicy(this, 'ResponseHeadersPolicy', {
82	        customHeadersBehavior: {
83	          customHeaders: [
84	            {
85	              header: 'Permissions-Policy',
86	              value:
87	                'accelerometer=(), camera=(), geolocation=(), gyroscope=(), magnetometer=(), microphone=(), payment=(), usb=(), interest-cohort=()',
88	              override: true,
89	            },
90	          ],
91	        },
92	        corsBehavior: {
93	          accessControlAllowCredentials: false,
94	          accessControlAllowOrigins: [config.appDomainName, 'https://ccda.medplum.com'],
95	          accessControlAllowHeaders: ['*'],
96	          accessControlAllowMethods: ['GET', 'HEAD', 'OPTIONS'],
97	          accessControlMaxAge: Duration.seconds(600),
98	          originOverride: false,
99	        },
100	        securityHeadersBehavior: {
101	          contentSecurityPolicy: {
102	            contentSecurityPolicy:
103	              "default-src 'none'; connect-src https://ccda.medplum.com; base-uri 'none'; form-action 'none'; frame-ancestors *;",
104	            override: true,
105	          },
106	          contentTypeOptions: { override: true },
107	          frameOptions: {
108	            frameOption: cloudfront.HeadersFrameOption.DENY,
109	            override: true,
110	          },
111	          referrerPolicy: {
112	            referrerPolicy: cloudfront.HeadersReferrerPolicy.NO_REFERRER,
113	            override: true,
114	          },
115	          strictTransportSecurity: {
116	            accessControlMaxAge: Duration.seconds(63072000),
117	            includeSubdomains: true,
118	            preload: true,
119	            override: true,
120	          },
121	          xssProtection: {
122	            protection: true,
123	            modeBlock: true,
124	            override: true,
125	          },
126	        },
127	      });
128	
129	      // WAF
130	      this.waf = buildWaf(
131	        this,
132	        'StorageWAF',
133	        `${config.stackName}-StorageWAF`,
134	        'CLOUDFRONT',
135	        config.storageWafIpSetArn,
136	        config.wafLogGroupName,
137	        config.wafLogGroupCreate
138	      );
139	
140	      // Origin access identity
141	      this.originAccessIdentity = new cloudfront.OriginAccessIdentity(this, 'OriginAccessIdentity', {});
142	      this.originAccessPolicyStatement = grantBucketAccessToOriginAccessIdentity(
143	        this.storageBucket,
144	        this.originAccessIdentity
145	      );
146	
147	      // CloudFront distribution
148	      this.distribution = new cloudfront.Distribution(this, 'StorageDistribution', {
149	        defaultBehavior: {
150	          origin: origins.S3BucketOrigin.withOriginAccessIdentity(this.storageBucket, {
151	            originAccessIdentity: this.originAccessIdentity,
152	          }),
153	          responseHeadersPolicy: this.responseHeadersPolicy,
154	          viewerProtocolPolicy: cloudfront.ViewerProtocolPolicy.REDIRECT_TO_HTTPS,
155	          trustedKeyGroups: [this.keyGroup],
156	        },
157	        certificate: acm.Certificate.fromCertificateArn(this, 'StorageCertificate', config.storageSslCertArn),
158	        domainNames: [config.storageDomainName],
159	        webAclId: this.waf.attrArn,
160	        logBucket: config.storageLoggingBucket
161	          ? s3.Bucket.fromBucketName(this, 'LoggingBucket', config.storageLoggingBucket)
162	          : undefined,
163	        logFilePrefix: config.storageLoggingPrefix,
164	      });
165	
166	      // DNS
167	      if (!config.skipDns) {
168	        const hostedZoneName = config.hostedZoneName ?? config.domainName.split('.').slice(-2).join('.');
169	        const zone = route53.HostedZone.fromLookup(this, 'Zone', { domainName: hostedZoneName });
170	
171	        // Route53 alias record for the CloudFront distribution
172	        this.dnsRecord = new route53.ARecord(this, 'StorageAliasRecord', {
173	          recordName: config.storageDomainName,
174	          target: route53.RecordTarget.fromAlias(new targets.CloudFrontTarget(this.distribution)),
175	          zone,
176	        });
177	      }
178	    }
179	  }
180	}
