/**
 * Determines whether the policy already contains a complete GuardDuty malware protection Deny statement.
 *
 * A statement is considered complete only if it uses the expected Sid, denies both
 * `s3:GetObject` and `s3:GetObjectVersion`, and has the expected malware scan status condition.
 *
 * @param policy - The bucket policy document.
 * @returns True if a complete GuardDuty malware protection statement already exists.
 */
function policyHasGuardDutyMalwareProtectionStatement(policy: Policy): boolean {
  return !!policy?.Statement?.some((s: PolicyStatement) => {
    return (
      s?.Sid === GUARDDUTY_MALWARE_PROTECTION_SID &&
      s?.Effect === 'Deny' &&
      Array.isArray(s?.Action) &&
      GUARDDUTY_MALWARE_PROTECTION_ACTIONS.every((action) => s.Action?.includes(action)) &&
      s?.Condition?.StringNotEquals?.[GUARDDUTY_MALWARE_SCAN_STATUS_TAG] === 'NO_THREATS_FOUND'
    );
  });
}

