 * Appends a GuardDuty malware protection Deny statement to the bucket policy.
 *
 * The statement denies reads of objects that have not been marked with a
 * `GuardDutyMalwareScanStatus` tag of `NO_THREATS_FOUND`. If a complete statement already exists,
 * this is a no-op to avoid duplicates.
 *
 * @param policy - The bucket policy document.
 * @param bucketName - The S3 bucket name.
 */
function addGuardDutyMalwareProtectionStatement(policy: Policy, bucketName: string): void {
  if (!policy.Version) {
    policy.Version = '2012-10-17';
  }

  if (!policy.Statement) {
    policy.Statement = [];
  }

  if (policyHasGuardDutyMalwareProtectionStatement(policy)) {
    return;
  }

  policy.Statement.push({
    Sid: GUARDDUTY_MALWARE_PROTECTION_SID,
    Effect: 'Deny',
    Action: [...GUARDDUTY_MALWARE_PROTECTION_ACTIONS],
    Resource: `arn:aws:s3:::${bucketName}/*`,
    Condition: {
      StringNotEquals: {
        [GUARDDUTY_MALWARE_SCAN_STATUS_TAG]: 'NO_THREATS_FOUND',
      },
    },
  });
